import React, { useState, useEffect } from "react";
import { collection, query, where, getDocs } from "firebase/firestore";
import { db, auth } from "../firebase-config";
import FeedCell from "./FeedCell"

function Feed({ isAuth, profileID }) {
    const [following, setFollowing] = useState([]);
    const [feed, setFeed] = useState([]);
    const [sortedFeed, setSortedFeed] = useState([]);
    const [checked, setChecked] = useState(false);

    // Fetch the global feed of public posts
    const getFeed = async () => {
        try {
            // Get all posts from the global feed
            const q = query(collection(db, "feed"));
            const querySnapshot = await getDocs(q);
            let allPosts = querySnapshot.docs.map((action) => ({ ...action.data() }));

            // Get all unique user IDs from posts
            const userIds = Array.from(new Set(allPosts.map(post => post.user)));
            // Fetch user privacy status in one go
            const usersRef = collection(db, "users");
            const userQuery = query(usersRef, where("id", "in", userIds.slice(0, 10)));
            // Firestore 'in' queries are limited to 10, so batch if needed
            let userPrivacyMap = {};
            for (let i = 0; i < userIds.length; i += 10) {
                const batchIds = userIds.slice(i, i + 10);
                const batchQuery = query(usersRef, where("id", "in", batchIds));
                const batchSnapshot = await getDocs(batchQuery);
                batchSnapshot.forEach(doc => {
                    const data = doc.data();
                    userPrivacyMap[data.id] = data.private || false;
                });
            }
            // Only show posts from public users
            const publicPosts = allPosts.filter(post => userPrivacyMap[post.user] === false);
            setChecked(true);
            setFeed(publicPosts);
        } catch (error) {
            console.error("Error fetching global feed:", error);
        }
    };


    const getUserFeed = async () => {
        try {
            const q = query(collection(db, "feed"), where("user", "==", profileID));
            const querySnapshot = await getDocs(q);

            if (querySnapshot.empty) {
                console.error("No user document found");
                return;
            }

            const userActions = querySnapshot.docs.map((action) => ({
                ...action.data()
            }));

            setChecked(true);
            setFeed(userActions);

        } catch (error) {
            console.error("Error fetching profiles:", error);
        }
    };



    // Sort feed when it's updated
    useEffect(() => {
        console.log(feed);
        if (feed.length > 0) {
            const sorted = feed
                .filter((item) => item.loggedFor && item.loggedOn) // Ensure action and date exist
                .sort((a, b) => new Date(b.loggedOn) - new Date(a.loggedOn)); // Sort by date
            setSortedFeed(sorted);
        }
    }, [feed]);

    useEffect(() => {
        if (profileID) {
            setFeed([]);
            setSortedFeed([]);
            getUserFeed();
        } else {
            setFeed([]);
            setSortedFeed([]);
            getFeed();
        }
    }, [isAuth, profileID]);

    return (
        <div className="feedContainer">
            {sortedFeed.length > 0 ? (
                <div className="feed">
                    {sortedFeed.map((actionObj, index) => {
                        return (<FeedCell action={actionObj} index={index} />);
                    })}
                </div>
            ) : (
                    <>
                        {
                            checked ?
                                <>
                                    {
                                        feed.length <= 0 && <p>No Actions to Show</p>
                                    }
                                </>
                                :
                                <p>Loading...</p>
                        }
                    </>
            )}
        </div>
    );
}

export default Feed;