import React, { useState, useEffect } from 'react';
import { setDoc, doc, query, collection, where, getDocs, getDoc, deleteDoc, updateDoc, arrayRemove, documentId } from "firebase/firestore";
import { db, auth, provider } from "../firebase-config";
import { onAuthStateChanged  } from "firebase/auth";
import ImgUpload from './ImgUpload';
import { useNavigate, useParams } from "react-router-dom";
import GetUserItems from "./GetUserItems";
import GenerateFit from "./GenerateFit";
import DisplayFit from "./DisplayFit";
import GetUserData from "./GetUserData";

function Closet({ isAuth }) {
        // Helper to generate 100 outfits and log tags
        const generate100Outfits = () => {
            if (!userItems || userItems.length === 0) {
                alert('No items to generate outfits!');
                return;
            }
            // Use the GenerateFit logic for randomizeFit
            // We'll need to simulate the function here
            const getRandomItems = (array, amt) => {
                if (!array || array.length === 0) return null;
                let returnItems = new Set();
                if (amt === 0) {
                    const item002 = array.find(item => item.id === "002");
                    if (item002) {
                        returnItems.add(item002);
                    }
                    return Array.from(returnItems);
                }
                while (returnItems.size < amt) {
                    returnItems.add(array[Math.floor(Math.random() * array.length)]);
                }
                return Array.from(returnItems);
            };
            const sortPrefItems = (items) => {
                const sorted = {
                    hats: [],
                    jackets: [],
                    tops: [],
                    bottoms: [],
                    shoes: [],
                    accessories: [],
                };
                sorted.hats = [...(items.filter(item => item.type === "Hat"))];
                sorted.jackets = [...(items.filter(item => item.type === "Jacket"))];
                sorted.tops = [...(items.filter(item => item.type === "Top"))];
                sorted.bottoms = [...(items.filter(item => item.type === "Bottoms"))];
                sorted.shoes = [...(items.filter(item => item.type === "Shoes"))];
                sorted.accessories = [...(items.filter(item => item.type === "Accessory"))];
                return(sorted);
            };
            const tags2D = [];
            let lastOutfit = null;
            for (let i = 0; i < 100; i++) {
                const sorted = sortPrefItems(userItems);
                const outfit = {
                    hat: sorted.hats.length > 0 ? getRandomItems(sorted.hats, 1)[0] : null,
                    jacket: sorted.jackets.length > 0 ? getRandomItems(sorted.jackets, 1)[0] : null,
                    top: sorted.tops.length > 0 ? getRandomItems(sorted.tops, 1)[0] : null,
                    bottom: sorted.bottoms.length > 0 ? getRandomItems(sorted.bottoms, 1)[0] : null,
                    shoe: sorted.shoes.length > 0 ? getRandomItems(sorted.shoes, 1)[0] : null,
                    accessories: sorted.accessories.length > 0 ? getRandomItems(sorted.accessories, Math.floor(Math.random() * 3)) : [],
                };
                // Collect tags
                let allTags = [];
                ['hat', 'jacket', 'top', 'bottom', 'shoe'].forEach(part => {
                    if (outfit[part] && outfit[part].tags) {
                        allTags = allTags.concat(outfit[part].tags);
                    }
                });
                if (outfit.accessories && Array.isArray(outfit.accessories)) {
                    outfit.accessories.forEach(acc => {
                        if (acc && acc.tags) {
                            allTags = allTags.concat(acc.tags);
                        }
                    });
                }
                allTags = Array.from(new Set(allTags));
                tags2D.push(allTags);
                lastOutfit = outfit;
            }
            // Pick a random outfit to display
            setCurFit(lastOutfit);
            console.log('2D array of tags for 100 outfits:', tags2D);
        };
    const [onMobile, setOnMobile] = useState(() => {
        return /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
      });
      

    const { profileId: paramProfileId } = useParams();
    const [currentID, setCurrentID] = useState();
    const [logging, setLogging] = useState(localStorage.getItem("logging"));
    const [date, setDate] = useState(localStorage.getItem("date"));
    const [displayFit, setDisplayFit] = useState(false)
    const [userItems, setUserItems] = useState(null);
    const [sortedItems, setSortedItems] = useState(null);
    const [curFit, setCurFit] = useState(null);
    const [hoveredItem, setHoveredItem] = useState(null);
    const [selectedCloset, setSelectedCloset] = useState("");
    const [subClosets, setSubClosets] = useState([]);
    const [showInvalidPopup, setShowInvalidPopup] = useState(false);
    const [lockedItems, setLockedItems] = useState(() => {
        if(localStorage.getItem("curFit")){
            let c = JSON.parse(localStorage.getItem("curFit"));
            return c;
        }
        else if(localStorage.getItem("item")){
            let i = JSON.parse(localStorage.getItem("item"));
            return {
                hat: i.type === "Hat" ? i : null,
                jacket: i.type === "Jacket" ? i : null,
                top: i.type === "Top" ? i : null,
                bottom: i.type === "Bottoms" ? i : null,
                shoe: i.type === "Shoes" ? i : null,
                accessories: i.type === "Accessory" ? [i] : [],
            };
        }
        return {
            hat: null,
            jacket: null,
            top: null,
            bottom: null,
            shoe: null,
            accessories: [],
        };
    });

    const clearLocked = () => {
        setLockedItems({
            hat: null,
            jacket: null,
            top: null,
            bottom: null,
            shoe: null,
            accessories: [],
        })
    }

    useEffect(() => {
        if(onMobile){
            document.body.style.overflow = 'hidden';
            document.body.style.position = 'fixed';
        }
        else{
            document.body.style.overflow = '';
            document.body.style.position = '';
        }

        return () => {
            document.body.style.overflow = '';
            document.body.style.position = '';
        }
    }, [onMobile])

    const updateUserItems = (curItems) => {
        setUserItems(curItems);
    }

    const loadCurFit = (newFit) => {
        setCurFit(newFit);
    }

    let navigate = useNavigate();

    useEffect(() => {
        if (paramProfileId) {
             if (paramProfileId.length === 28) {                  // user profile
                 setCurrentID(paramProfileId);
                 getClosetFromCode(paramProfileId);
             } else if (paramProfileId.length === 8) {            // closet code
                 setSelectedCloset(paramProfileId);
                 getClosetFromCode(paramProfileId);
             } else {            
                 setDisplayFit(true);
                 getFitFromCode(paramProfileId);
             }
        } else {
            const unsubscribe = onAuthStateChanged(auth, (user) => {
                if (user) {
                    setCurrentID(user.uid);
                    navigate("/" + user.uid);
                } else {
                    navigate("/login");
                }
            });

            return () => unsubscribe();
        }
    }, [paramProfileId, isAuth, navigate]);


    const getFitFromCode = async (outfitID) => {
        if (isAuth) {
            getClosetFromCode(paramProfileId);
        }
        const outfit = {
            hat: null,
            jacket: null,
            top: null,
            bottom: null,
            shoe: null,
            accessories: [],
        };
            let cats = Object.keys(outfit);
            for(let i = 0; i < 5; i++){
                let curID = outfitID.substr(i * 10, 10);

                if(curID === "0000000000"){
                    curID = "000";
                }
                if(curID === "0000000001"){
                    curID = "001";
                }
                
                const b = query(collection(db, "clothing"), where("id", "==", curID));
                const data = await getDocs(b);
                data.forEach((doc) => {
                    outfit[cats[i]] = doc.data();
                });
        }

        let accs = outfitID.substring(52, outfitID.length - 2);
        console.log("accs", accs);

        for (let i = 0; i < accs.length / 10; i++) {
            let curID = accs.substr(i * 10, 10);

            if (curID === "0000000002") {
                curID = "002";
            }

            const b = query(collection(db, "clothing"), where("id", "==", curID));
            const data = await getDocs(b);
            data.forEach((doc) => {
                outfit.accessories.push(doc.data());
            });
        }
        
        setCurFit(outfit)

    }

    useEffect(() => {
        if (userItems && userItems.length > 0) {
            const sorted = sortUserItems();
            if (selectedCloset && (sorted.tops.length < 1 || sorted.bottoms.length < 1 || sorted.shoes.length < 1)) {
                setSortedItems(null); // Prevent showing invalid closet
                setShowInvalidPopup(true);
                // Delete the invalid subcloset
                const deleteInvalidCloset = async () => {
                    try {
                        await deleteDoc(doc(db, "closets", selectedCloset));
                        const uid = currentID || auth.currentUser.uid;
                        const toRemove = subClosets.find(c => c.id === selectedCloset);
                        if (toRemove) {
                            await updateDoc(doc(db, "users", uid), {
                                subclosets: arrayRemove(toRemove)
                            });
                        }
                        setSubClosets(prev => prev.filter(c => c.id !== selectedCloset));
                        setSelectedCloset("");
                        setShowInvalidPopup(false);
                        navigate("/" + uid);
                    } catch (err) {
                        console.error("Failed to delete invalid closet:", err);
                        setShowInvalidPopup(false);
                    }
                };
                deleteInvalidCloset();
            } else {
                setSortedItems(sorted);
            }
        }
    }, [userItems, selectedCloset, currentID, navigate]);

    useEffect(() => {
        if (!currentID) return;

        // read once; if you want live updates use onSnapshot instead
        getDoc(doc(db, "users", currentID)).then(snap => {
            if (snap.exists()) {
                let closets = snap.data().subclosets;
                if (!Array.isArray(closets)) {
                    closets = [];
                } else {
                    if (closets.length > 0 && typeof closets[0] === 'string') {
                        // old format, convert
                        closets = closets.map(code => ({id: code, name: code}));
                        // update the doc
                        updateDoc(doc(db, "users", currentID), { subclosets: closets });
                    }
                }
                setSubClosets(closets);
            } else {
                setSubClosets([]);            // no document yet → empty array
            }
        });
    }, [currentID]);

    const sortUserItems = () => {
        const sorted = {
            hats: [],
            jackets: [],
            tops: [],
            bottoms: [],
            shoes: [],
            accessories: [],
        };

        sorted.hats = userItems.filter(item => item.type === "Hat");
        sorted.jackets = userItems.filter(item => item.type === "Jacket");
        sorted.tops = userItems.filter(item => item.type === "Top");
        sorted.bottoms = userItems.filter(item => item.type === "Bottoms");
        sorted.shoes = userItems.filter(item => item.type === "Shoes");
        sorted.accessories = userItems.filter(item => item.type === "Accessory");

        
        if(sorted.tops.length < 1 || sorted.bottoms.length < 1 || sorted.shoes.length < 1){
            if (!selectedCloset) {
                if (isAuth) {
                    navigate("/tagitems");
                }
                else {
                    navigate("/search");
                }
            }
        }

        return sorted;
    }

    const fetchClothes = async ids => {
        const unique = [...new Set(ids)];      // no duplicates
        const chunks = [];
        while (unique.length) chunks.push(unique.splice(0, 10)); // 10 ids / chunk

        const promises = chunks.map(chunk => {
            const q = query(collection(db, "clothing"),
                where(documentId(), "in", chunk));

            return getDocs(q);
        });

        const snaps = await Promise.all(promises);   // ❷  1–15 requests TOTAL
        const result = [];
        snaps.forEach(snap =>
            snap.forEach(doc => result.push({ id: doc.id, ...doc.data() }))
        );
        return result;
    };

   // ---------- turn an 8-char closet code into userItems -------------
    const getClosetFromCode = async closetId => {

        let ids = [];

        if (paramProfileId.length === 28) {
            const snap = await getDoc(doc(db, "users", paramProfileId));
            if (!snap.exists()) { console.warn("No such closet"); return; }

            snap.data().items.forEach((item) => {
                ids.push(item.id);
            });
        }
        else if (paramProfileId.length === 8) {
            const snap = await getDoc(doc(db, "closets", closetId));
            if (!snap.exists()) { console.warn("No such closet"); return; }

            const monster = snap.data().items ?? "";   // big concatenated string

            // 1️⃣  ensure the three placeholder ids are present
            ["000", "001", "002"].forEach(id => {
                if (!ids.includes(id)) ids.push(id);
            });

            // pull the 10-character ids out of the monster string
            for (let i = 0; i < monster.length; i += 10) {
                ids.push(monster.substr(i, 10));
            }

        } else {
            const snap = await getDoc(doc(db, "users", auth.currentUser.uid));
            if (!snap.exists()) { console.warn("No such closet"); return; }

            snap.data().items.forEach((item) => {
                console.log(item.id);
                ids.push(item.id);
            });
        }

        console.log(ids);

        const clothes = await fetchClothes(ids);   // ⇦ batched version
        setUserItems(clothes);
    };

    const updateCurFit = (item) => {
        let cur = { ...curFit };
        
        if (!cur.accessories) {
            cur.accessories = [];
        }
    
        switch (item.type) {
            case "Hat":
                cur.hat = item;
                break;
            case "Jacket":
                cur.jacket = item;
                break;
            case "Top":
                cur.top = item;
                break;
            case "Bottoms":
                cur.bottom = item;
                break;
            case "Shoes":
                cur.shoe = item;
                break;
            case "Accessory":
                if (!Array.isArray(cur.accessories)) {
                    cur.accessories = [];
                }
                
                if (cur.accessories.some(acc => acc.id === item.id)) {
                    cur.accessories = cur.accessories.filter(acc => acc.id !== item.id);
                } else {
                    cur.accessories.push(item);
                }
                break;
            default:
                break;
        }
        setCurFit(cur);
    }

    const toggleLockItem = (item) => {
        localStorage.removeItem("curFit");
        localStorage.removeItem("item");
        setLockedItems(prevLockedItems => {
            let updatedLockedItems = { ...prevLockedItems };
            
            switch (item.type) {
                case "Hat":
                    updatedLockedItems.hat = updatedLockedItems.hat ? null : item;
                    break;
                case "Jacket":
                    updatedLockedItems.jacket = updatedLockedItems.jacket ? null : item;
                    break;
                case "Top":
                    updatedLockedItems.top = updatedLockedItems.top ? null : item;
                    break;
                case "Bottoms":
                    updatedLockedItems.bottom = updatedLockedItems.bottom ? null : item;
                    break;
                case "Shoes":
                    updatedLockedItems.shoe = updatedLockedItems.shoe ? null : item;
                    break;
                case "Accessory":
                    if (updatedLockedItems.accessories.some(acc => acc.id === item.id)) {
                        updatedLockedItems.accessories = updatedLockedItems.accessories.filter(acc => acc.id !== item.id);
                    } else {
                        updatedLockedItems.accessories.push(item);
                    }
                    break;
                default:
                    break;
            }

            return updatedLockedItems;
        });
    }

    const getLockIcon = (item) => {
        let isLocked = false;
        
        switch (item.type) {
            case "Hat":
                isLocked = lockedItems.hat && lockedItems.hat.id === item.id;
                break;
            case "Jacket":
                isLocked = lockedItems.jacket && lockedItems.jacket.id === item.id;
                break;
            case "Top":
                isLocked = lockedItems.top && lockedItems.top.id === item.id;
                break;
            case "Bottoms":
                isLocked = lockedItems.bottom && lockedItems.bottom.id === item.id;
                break;
            case "Shoes":
                isLocked = lockedItems.shoe && lockedItems.shoe.id === item.id;
                break;
            case "Accessory":
                isLocked = lockedItems.accessories.some(acc => acc.id === item.id);
                break;
            default:
                break;
        }

        return isLocked ? '🔒' : '🔓'; // You can use actual icons/images instead of these emojis
    }

    // Determine the background style based on whether the item is included in curFit
    const getItemStyle = (item) => {
        try{
            if(curFit !== null){
                if (curFit.hat.id === item.id ||
                    curFit.jacket.id === item.id ||
                    curFit.top.id === item.id ||
                    curFit.bottom.id === item.id ||
                    curFit.shoe.id === item.id ||
                    (Array.isArray(curFit.accessories) && curFit.accessories.some(acc => acc.id === item.id))) {
                    return {
                        backgroundColor: '#333333',
                        transition: 'background-color 0.3s ease',
                        position: 'relative'
                    };
                }
                if (hoveredItem === item.id) {
                    return {
                        backgroundColor: 'rgba(164, 164, 164, 0.5)', // Light gray background on hover
                        transition: 'background-color 0.3s ease'
                    };
                }
                return {backgroundColor: 'var(--color4)'};
            }
        }
        catch(error){
            console.log(error, "item causing error", curFit);
        }
    }

    const renderLockIcon = (item) => {
            if (curFit && (
                curFit.hat?.id === item.id ||
                curFit.jacket?.id === item.id ||
                curFit.top?.id === item.id ||
                curFit.bottom?.id === item.id ||
                curFit.shoe?.id === item.id ||
                (Array.isArray(curFit.accessories) && curFit.accessories.some(acc => acc.id === item.id))
            )) {
                return (
                    <div className="lockIcon" onClick={(e) => { e.stopPropagation(); toggleLockItem(item); }}>
                        {getLockIcon(item)}
                    </div>
                );
            }
        return null;
    }

    const goProfile = async () => {
        if (currentID) {
            navigate(`/profile/${currentID}`)
        }
        else {
            navigate(`/profile/${curFit.top.owner}`)
        }
    }

    const genFitCode = async (curFit) => {
        if (!curFit) return;
        let fitCode = "";
        console.log("curFit:", curFit);
        let keys = Object.keys(curFit);

        keys.forEach((key) => {
            const item = curFit[key];

            if (key === "accessories" && Array.isArray(item) && item.length > 0) {
                fitCode += "--";
                item.forEach((obj) => {
                    if (obj.id) {
                        if (obj.id.length < 10) {
                            fitCode += ("0000000" + obj.id);
                        } else {
                            fitCode += obj.id;
                        }
                    } else {
                        console.error(`Missing id in Accessories object:`, obj);
                    }
                });
                fitCode += "--";
            } else if (key === "accessories" && Array.isArray(item) && item.length === 0) {
                fitCode += "----";
            }

            if (item && item.id && key !== "accessories") {
                if (item.id.length < 10) {
                    fitCode += ("0000000" + item.id);
                } else {
                    fitCode += item.id;
                }
            } else {
                console.error(`Invalid or missing 'id' for key '${key}':`, item);
            }
        });

        console.log("Generated fitCode:", fitCode);
        return (fitCode);
    };

    const deleteCloset = async () => {
        // nothing selected or trying to delete the default wardrobe
        if (!selectedCloset) {
            alert("Select a sub-closet first.");
            return;
        }

        const ok = window.confirm(
            `Permanently delete sub-closet "${subClosets.find(c => c.id === selectedCloset)?.name || selectedCloset}"?`
        );
        if (!ok) return;

        try {
            /* 1️⃣  remove the closet document itself */
            await deleteDoc(doc(db, "closets", selectedCloset));

            /* 2️⃣  remove the code from the user’s subclosets array */
            const uid = currentID || auth.currentUser.uid;
            const toRemove = subClosets.find(c => c.id === selectedCloset);
            if (toRemove) {
                await updateDoc(doc(db, "users", uid), {
                    subclosets: arrayRemove(toRemove)
                });
            }

            /* 3️⃣  update local state / UI */
            setSubClosets(prev => prev.filter(c => c.id !== selectedCloset));
            setSelectedCloset("");        // back to default garments
            navigate("/" + uid);

            alert("Closet deleted.");
        } catch (err) {
            console.error("Failed to delete closet:", err);
            alert("Something went wrong – closet not deleted.");
        }
    };

    const matchFit = async () => {
        const fitCode = await genFitCode(curFit);
        if (fitCode) {
            navigate(`/matchfit/${fitCode}`);
        }
    };

    return (
        <div>
            <button onClick={generate100Outfits} style={{marginBottom:8}}>Generate 100 Outfits (log tags)</button>
            {sortedItems ? (
                <>
                <div style={{ display:"flex", gap:"10px", alignItems:"center" }}>
                     <button onClick={goProfile}>View Profile</button>
 
                     {/* -------- Garments dropdown -------- */}
                        <select
                            value={selectedCloset}
                            onChange={e => {
                                const val = e.target.value;
                                setSelectedCloset(val);
                                if (!val) {
                                    navigate("/" + currentID);         // default full closet
                                } else {
                                    navigate("/" + val);               // 8-char code → useEffect loads it
                                }
                            }}>
                            <option value="">Default garments</option>
                            {subClosets.filter(closet => typeof closet === 'object' && closet.id && closet.name && typeof closet.name === 'string').map(closet => (
                                <option key={closet.id} value={closet.id}>{closet.name}</option>
                            ))}
                        </select>
 
                     {/* -------- Style dropdown (empty for now) -------- */}
                     <select disabled>
                        <option>Style</option>
                        </select>

                        {selectedCloset &&
                            <button onClick={deleteCloset}>
                                Delete Closet
                            </button>
                        }
                 </div>
                <div className='closetContainer'>
                    <div className="leftCloset scroll-container">
                        <div className="articleDisplay scroll-container">
                            {sortedItems.hats.length > 0 ?
                                <>
                                    {sortedItems.hats.map((item) => (
                                        <div
                                            className="itemContainer"
                                            onClick={() => (!lockedItems.hat && updateCurFit(item))}
                                            onMouseEnter={() => setHoveredItem(item.id)}
                                            onMouseLeave={() => setHoveredItem(null)}
                                            key={item.id}
                                        >
                                            <img src={item.imgURL} alt="hat" className='closetItemImg' 
                                            style={getItemStyle(item)}/>
                                            {renderLockIcon(item)}
                                        </div>
                                    ))}
                                </>
                                :
                                <p>no hats</p>
                            }
                        </div>
                        <div className="articleDisplay scroll-container">
                            {sortedItems.tops.length > 0 ?
                                <>
                                    {sortedItems.tops.map((item) => (
                                        <div
                                            className="itemContainer"
                                            onClick={() => (!lockedItems.top && updateCurFit(item))}
                                            onMouseEnter={() => setHoveredItem(item.id)}
                                            onMouseLeave={() => setHoveredItem(null)}
                                            key={item.id}
                                        >
                                            <img src={item.imgURL} alt="top" className='closetItemImg' 
                                            style={getItemStyle(item)}/>
                                            {renderLockIcon(item)}
                                        </div>
                                    ))}
                                </>
                                :
                                <p>no tops</p>
                            }
                        </div>
                        <div className="articleDisplay scroll-container">
                            {sortedItems.accessories.length > 0 ?
                                <>
                                    {sortedItems.accessories.map((item) => {
                                        if(item.id !== "002"){
                                            return(
                                                <div
                                                    className="itemContainer"
                                                    onClick={() => (lockedItems.accessories.length === 0 && updateCurFit(item))}
                                                    onMouseEnter={() => setHoveredItem(item.id)}
                                                    onMouseLeave={() => setHoveredItem(null)}
                                                    key={item.id}
                                                >
                                                    <img src={item.imgURL} alt="accessory" className='closetItemImg' 
                                                    style={getItemStyle(item)} />
                                                    {renderLockIcon(item)}
                                                </div>
                                            )
                                        }
                                    })}
                                </>
                                :
                                <p>no accessories</p>
                            }
                        </div>
                    </div>
                    <div className="midCloset" style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', width: '100%' }}>
                        {/* Operational buttons and tag bar always visible above scrollable fit */}
                        <div style={{ width: '100%', maxWidth: '500px', margin: '0 auto', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '16px', marginBottom: '20px' }}>
                            {curFit && <button onClick={matchFit} className="rerollButton">Match This Fit</button>}
                        </div>
                        <div className="scroll-container" style={{ width: '100%', maxWidth: '500px', margin: '0 auto', overflowY: 'auto', flex: 1 }}>
                            <GenerateFit userItems={userItems} passFit={curFit} setNewFit={loadCurFit} baseItems={lockedItems} clearLockedItems={clearLocked} id={currentID} date={date} logging={logging}/>
                        </div>
                    </div>
                    <div className="rightCloset scroll-container">
                        <div className="articleDisplay scroll-container">
                            {sortedItems.jackets.length > 0 ?
                                <>
                                    {sortedItems.jackets.map((item) => (
                                        <div
                                            className="itemContainer"
                                            onClick={() => (!lockedItems.jacket && updateCurFit(item))}
                                            onMouseEnter={() => setHoveredItem(item.id)}
                                            onMouseLeave={() => setHoveredItem(null)}
                                            key={item.id}
                                        >
                                            <img src={item.imgURL} alt="jacket" className='closetItemImg' 
                                            style={getItemStyle(item)}/>
                                            {renderLockIcon(item)}
                                        </div>
                                    ))}
                                </>
                                :
                                <p>no jackets</p>
                            }
                        </div>
                        <div className="articleDisplay scroll-container">
                            {sortedItems.bottoms.length > 0 ?
                                <>
                                    {sortedItems.bottoms.map((item) => (
                                        <div
                                            className="itemContainer"
                                            onClick={() => (!lockedItems.bottom && updateCurFit(item))}
                                            onMouseEnter={() => setHoveredItem(item.id)}
                                            onMouseLeave={() => setHoveredItem(null)}
                                            key={item.id}
                                        >
                                            <img src={item.imgURL} alt="bottom" className='closetItemImg' 
                                            style={getItemStyle(item)}/>
                                            {renderLockIcon(item)}
                                        </div>
                                    ))}
                                </>
                                :
                                <p>no bottoms</p>
                            }
                        </div>
                        <div className="articleDisplay scroll-container">
                            {sortedItems.shoes.length > 0 ?
                                <>
                                    {sortedItems.shoes.map((item) => (
                                        <div
                                            className="itemContainer"
                                            onClick={() => (!lockedItems.shoe && updateCurFit(item))}
                                            onMouseEnter={() => setHoveredItem(item.id)}
                                            onMouseLeave={() => setHoveredItem(null)}
                                            key={item.id}
                                        >
                                            <img src={item.imgURL} alt="shoes" className='closetItemImg' 
                                            style={getItemStyle(item)}/>
                                            {renderLockIcon(item)}
                                        </div>
                                    ))}
                                </>
                                :
                                <p>no shoes</p>
                            }
                        </div>
                    </div>
                    </div>
                </>
            ) : (
                <>
                        {(displayFit && curFit) ?
                            <>
                                <button onClick={() => { goProfile() }}>View Profile</button>
                                <div style={{ width: "200px", margin: "auto" }} >
                                    <DisplayFit fit={curFit} />
                                </div>
                            </>
                            :
                            <p>Loading...</p>

                    }
                 </>
            )}
            {showInvalidPopup && (
                <div style={{
                    position: 'fixed',
                    top: '50%',
                    left: '50%',
                    transform: 'translate(-50%, -50%)',
                    backgroundColor: 'rgba(0, 0, 0, 0.8)',
                    color: 'white',
                    padding: '20px',
                    borderRadius: '10px',
                    zIndex: 1000,
                    textAlign: 'center'
                }}>
                    <p>The subcloset is invalid and has been deleted.</p>
                </div>
            )}
        </div>
    );    
}

export default Closet;